std::string dst;
uint32_t v = 128;
// Test case: 128 should be encoded as two bytes: 0x80 0x01
// First byte: 128 & 0x7F = 0, then set continuation bit: 0 | 0x80 = 0x80
// Second byte: (128 >> 7) = 1, then no continuation bit: 1
while (v >= 0x80) {
  dst.push_back(static_cast<char>(v | 0x80));
  v >>= 7;
}
dst.push_back(static_cast<char>(v));

